import 'package:flutter/material.dart';import 'package:flutter_screenutil/flutter_screenutil.dart';import '../../../../Config/Assets/images.dart';import '../../../Authentication/presentation/widgets/banner_card.dart';class CustomSliverGridBuilder extends StatelessWidget {  const CustomSliverGridBuilder({    super.key,  });  @override  Widget build(BuildContext context) {    return SliverGrid.builder(      gridDelegate: SliverGridDelegateWithFixedCrossAxisCount(        crossAxisCount: (1.sw ~/ 150).clamp(1, 4).toInt(),        mainAxisSpacing: 21.h,        crossAxisSpacing: 21.w,        childAspectRatio: 156.w / 225.h,      ),      itemCount: 13,      itemBuilder: (_, index) {        return BannerCard(          caption:              "Lokman Sofa Premium",          imagePath: AppImages.testPhoto,          price: r"$500",        );      },    );  }}